"""ContentWriter: the only code that writes content files. The LLM never chooses paths:
they are derived from validated lesson ids and confined to the content root."""

from pathlib import Path

from contentkit.models import Lesson
from contentkit.yamlio import content_hash, dump_yaml, load_yaml, to_data, write_text_atomic

HEADER = (
    "# Generated by the local LLM; reviewed in Django Admin. "
    "Edit freely: manual edits are detected.\n"
)


class WriteConflict(Exception):
    pass


class ContentWriter:
    def __init__(self, root: Path) -> None:
        self.root = root.resolve()

    def _confined(self, path: Path) -> Path:
        resolved = path.resolve()
        if not resolved.is_relative_to(self.root):
            raise ValueError(f"refusing to write outside the content root: {path}")
        return resolved

    def lesson_path(self, lesson: Lesson) -> Path:
        # Lesson ids are validated slugs and levels are a closed set, so these paths are safe.
        return self._confined(self.root / "lessons" / lesson.level.lower() / f"{lesson.id}.yaml")

    def draft_path(self, lesson: Lesson, job_id: int) -> Path:
        name = f"{lesson.id}.job-{job_id}.yaml"
        return self._confined(self.root / "drafts" / lesson.level.lower() / name)

    def read_lesson(self, path: Path) -> Lesson | None:
        path = self._confined(path)
        return Lesson.model_validate(load_yaml(path)) if path.exists() else None

    def current_hash(self, lesson_id: str, level: str) -> str:
        path = self._confined(self.root / "lessons" / level.lower() / f"{lesson_id}.yaml")
        current = self.read_lesson(path)
        return content_hash(current) if current else ""

    def write_draft(self, lesson: Lesson, job_id: int) -> Path:
        path = self.draft_path(lesson, job_id)
        write_text_atomic(path, HEADER + dump_yaml(to_data(lesson)))
        return path

    def promote(
        self, draft: Lesson, *, base_hash: str, allow_overwrite_edits: bool = False
    ) -> Path:
        """Write an approved draft to content/lessons/. Refuses if the published file changed
        since the job started, or (for fresh generations) if it holds manual edits."""
        target = self.lesson_path(draft)
        current = self.read_lesson(target)
        current_hash = content_hash(current) if current else ""
        if current_hash != base_hash:
            raise WriteConflict(f"{target.name} changed since this draft was generated")
        edited = bool(
            current and current.provenance and current.provenance.generated_hash != current_hash
        )
        if edited and not allow_overwrite_edits:
            raise WriteConflict(f"{target.name} has manual edits; approving would overwrite them")
        write_text_atomic(target, HEADER + dump_yaml(to_data(draft)))
        return target
